def inverse_fermi_dirac_integral_half_polylog_newton(P, A, lambda_i, alpha, tau, x, n=None):
    '''This function uses the Newton-Raphson method to find the root of an implicit function.
    Inputs:
    P (float): incident optical power in W
    A (float): beam area in μm^2
    lambda_i (float): incident wavelength in nm
    alpha (float): absorption coefficient in cm^-1
    tau (float): lifetime of excess carriers in s
    x (float): depth variable in μm
    n (float): electron density, which is unknown at default (set as None)
    Outputs:
    Ef: Fermi level
    '''
    # If carrier density is not given, compute it from the generation function
    if n is None:
        n = generation(P, A, lambda_i, alpha, tau, x)

    n = np.asarray(n, dtype=float)

    Vt = 0.0259  # thermal voltage (V)

    def solve_single(n_val):
        if n_val <= 0:
            return np.nan
        # Function whose root gives the Fermi level
        func = lambda Ef: fermi_dirac_integral_half_polylog(Ef) - n_val
        # Initial guess from Boltzmann (non-degenerate) approximation
        Nc = fermi_dirac_integral_half_polylog(0.0) / 0.7651470246   # F_1/2(0) = 0.7651...
        try:
            Ef0 = Vt * np.log(n_val / Nc)
        except Exception:
            Ef0 = 0.0
        if not np.isfinite(Ef0):
            Ef0 = 0.0
        try:
            Ef = newton(func, Ef0, tol=1e-12, maxiter=200)
        except (RuntimeError, RuntimeWarning, OverflowError):
            # Fallback: bisection
            lo, hi = -5.0, 5.0
            for _ in range(200):
                mid = 0.5 * (lo + hi)
                if func(mid) > 0:
                    hi = mid
                else:
                    lo = mid
            Ef = 0.5 * (lo + hi)
        return Ef

    if n.ndim == 0:
        return solve_single(float(n))
    else:
        return np.array([solve_single(float(val)) for val in n.ravel()]).reshape(n.shape)
